mapper.select:
SELECT * FROM second_hand_product 
WHERE user_name = #{userName}
ORDER BY create_time DESC

mapper.insert:
INSERT INTO second_hand_product (
    user_name, product_name, product_description, product_condition,
    price, original_price, product_images, category, status
) VALUES (
    #{userName}, #{productName}, #{productDescription}, #{productCondition},
    #{price}, #{originalPrice}, #{productImages}, #{category}, #{status}
)

mapper.update:
UPDATE second_hand_product 
SET view_count = view_count + 1 
WHERE product_id = #{productId}

UPDATE second_hand_product 
SET want_count = want_count + 1 
WHERE product_id = #{productId}

UPDATE second_hand_product 
SET status = #{status}
WHERE product_id = #{productId}
